INSERT INTO contoh_soal (id,kode_contoh,tingkat,urutan,sub_materi,capaian_pembelajaran,tujuan_pembelajaran,pertanyaan,pilihan_a,pilihan_b,pilihan_c,pilihan_d,pilihan_e,jawaban_benar,hint_1,hint_2,pembahasan,feedback_salah,metadata_verifikasi,aktif) VALUES (1,'CON-R-001','rendah',1,'notasi_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Mengenali fungsi yang dikerjakan lebih dahulu pada notasi komposisi.','Jika f(x)=2x+1 dan g(x)=x+1, bentuk (f o g)(x) sebelum disederhanakan adalah ...','f(g(x))','g(f(x))','f(x)+g(x)','f(x)g(x)','f(x)-g(x)','a','Perhatikan fungsi yang paling dekat dengan x pada notasi komposisi.','Pada (f o g)(x), kerjakan g terlebih dahulu, lalu masukkan hasilnya ke f.','(f o g)(x)=f(g(x)). Huruf di kanan, yaitu g, bekerja lebih dahulu; keluarannya menjadi masukan f.','{"a": "", "b": "Urutan tertukar: g(f(x)) adalah (g o f)(x).", "c": "Komposisi bukan penjumlahan dua nilai fungsi.", "d": "Komposisi berarti substitusi, bukan perkalian fungsi.", "e": "Komposisi tidak dibentuk dengan pengurangan fungsi."}','{"kind": "literal", "expected": "f(g(x))"}',1),(2,'CON-R-002','rendah',2,'notasi_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Mengenali fungsi yang dikerjakan lebih dahulu pada notasi komposisi.','Jika f(x)=3x+1 dan g(x)=x+2, bentuk (f o g)(x) sebelum disederhanakan adalah ...','f(x)-g(x)','f(g(x))','g(f(x))','f(x)+g(x)','f(x)g(x)','b','Perhatikan fungsi yang paling dekat dengan x pada notasi komposisi.','Pada (f o g)(x), kerjakan g terlebih dahulu, lalu masukkan hasilnya ke f.','(f o g)(x)=f(g(x)). Huruf di kanan, yaitu g, bekerja lebih dahulu; keluarannya menjadi masukan f.','{"a": "Komposisi tidak dibentuk dengan pengurangan fungsi.", "b": "", "c": "Urutan tertukar: g(f(x)) adalah (g o f)(x).", "d": "Komposisi bukan penjumlahan dua nilai fungsi.", "e": "Komposisi berarti substitusi, bukan perkalian fungsi."}','{"kind": "literal", "expected": "f(g(x))"}',1),(3,'CON-R-003','rendah',3,'notasi_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Mengenali fungsi yang dikerjakan lebih dahulu pada notasi komposisi.','Jika f(x)=4x+1 dan g(x)=x+3, bentuk (f o g)(x) sebelum disederhanakan adalah ...','f(x)g(x)','f(x)-g(x)','f(g(x))','g(f(x))','f(x)+g(x)','c','Perhatikan fungsi yang paling dekat dengan x pada notasi komposisi.','Pada (f o g)(x), kerjakan g terlebih dahulu, lalu masukkan hasilnya ke f.','(f o g)(x)=f(g(x)). Huruf di kanan, yaitu g, bekerja lebih dahulu; keluarannya menjadi masukan f.','{"a": "Komposisi berarti substitusi, bukan perkalian fungsi.", "b": "Komposisi tidak dibentuk dengan pengurangan fungsi.", "c": "", "d": "Urutan tertukar: g(f(x)) adalah (g o f)(x).", "e": "Komposisi bukan penjumlahan dua nilai fungsi."}','{"kind": "literal", "expected": "f(g(x))"}',1),(4,'CON-R-004','rendah',4,'notasi_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Mengenali fungsi yang dikerjakan lebih dahulu pada notasi komposisi.','Jika f(x)=5x+1 dan g(x)=x+4, bentuk (f o g)(x) sebelum disederhanakan adalah ...','f(x)+g(x)','f(x)g(x)','f(x)-g(x)','f(g(x))','g(f(x))','d','Perhatikan fungsi yang paling dekat dengan x pada notasi komposisi.','Pada (f o g)(x), kerjakan g terlebih dahulu, lalu masukkan hasilnya ke f.','(f o g)(x)=f(g(x)). Huruf di kanan, yaitu g, bekerja lebih dahulu; keluarannya menjadi masukan f.','{"a": "Komposisi bukan penjumlahan dua nilai fungsi.", "b": "Komposisi berarti substitusi, bukan perkalian fungsi.", "c": "Komposisi tidak dibentuk dengan pengurangan fungsi.", "d": "", "e": "Urutan tertukar: g(f(x)) adalah (g o f)(x)."}','{"kind": "literal", "expected": "f(g(x))"}',1),(5,'CON-R-005','rendah',5,'notasi_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Mengenali fungsi yang dikerjakan lebih dahulu pada notasi komposisi.','Jika f(x)=6x+1 dan g(x)=x+5, bentuk (f o g)(x) sebelum disederhanakan adalah ...','g(f(x))','f(x)+g(x)','f(x)g(x)','f(x)-g(x)','f(g(x))','e','Perhatikan fungsi yang paling dekat dengan x pada notasi komposisi.','Pada (f o g)(x), kerjakan g terlebih dahulu, lalu masukkan hasilnya ke f.','(f o g)(x)=f(g(x)). Huruf di kanan, yaitu g, bekerja lebih dahulu; keluarannya menjadi masukan f.','{"a": "Urutan tertukar: g(f(x)) adalah (g o f)(x).", "b": "Komposisi bukan penjumlahan dua nilai fungsi.", "c": "Komposisi berarti substitusi, bukan perkalian fungsi.", "d": "Komposisi tidak dibentuk dengan pengurangan fungsi.", "e": ""}','{"kind": "literal", "expected": "f(g(x))"}',1),(6,'CON-R-006','rendah',6,'notasi_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Mengenali fungsi yang dikerjakan lebih dahulu pada notasi komposisi.','Jika f(x)=7x+1 dan g(x)=x+6, bentuk (f o g)(x) sebelum disederhanakan adalah ...','f(g(x))','g(f(x))','f(x)+g(x)','f(x)g(x)','f(x)-g(x)','a','Perhatikan fungsi yang paling dekat dengan x pada notasi komposisi.','Pada (f o g)(x), kerjakan g terlebih dahulu, lalu masukkan hasilnya ke f.','(f o g)(x)=f(g(x)). Huruf di kanan, yaitu g, bekerja lebih dahulu; keluarannya menjadi masukan f.','{"a": "", "b": "Urutan tertukar: g(f(x)) adalah (g o f)(x).", "c": "Komposisi bukan penjumlahan dua nilai fungsi.", "d": "Komposisi berarti substitusi, bukan perkalian fungsi.", "e": "Komposisi tidak dibentuk dengan pengurangan fungsi."}','{"kind": "literal", "expected": "f(g(x))"}',1),(7,'CON-R-007','rendah',7,'nilai_dan_rumus_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menghitung nilai komposisi dua fungsi linear secara berurutan.','Diketahui f(x)=3x+2 dan g(x)=x+2. Nilai (f o g)(1) adalah ...','8','11','12','10','14','b','Mulailah dengan menghitung g(1).','g(1)=3. Substitusikan nilai ini ke f.','g(1)=1+2=3. Selanjutnya f(3)=3(3)+2=11.','{"a": "Anda mungkin mengurangi koefisien f; ikuti operasi pada rumus f apa adanya.", "b": "", "c": "Nilainya satu lebih besar; periksa kembali penjumlahan konstanta terakhir.", "d": "Nilainya satu lebih kecil; jangan mengurangi konstanta pada f.", "e": "Anda mungkin menambahkan koefisien f sekali lagi setelah substitusi."}','{"a": 3, "b": 2, "c": 2, "x": 1, "kind": "compose_linear_value"}',1),(8,'CON-R-008','rendah',8,'nilai_dan_rumus_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menghitung nilai komposisi dua fungsi linear secara berurutan.','Diketahui f(x)=4x+3 dan g(x)=x+3. Nilai (f o g)(2) adalah ...','27','19','23','24','22','c','Mulailah dengan menghitung g(2).','g(2)=5. Substitusikan nilai ini ke f.','g(2)=2+3=5. Selanjutnya f(5)=4(5)+3=23.','{"a": "Anda mungkin menambahkan koefisien f sekali lagi setelah substitusi.", "b": "Anda mungkin mengurangi koefisien f; ikuti operasi pada rumus f apa adanya.", "c": "", "d": "Nilainya satu lebih besar; periksa kembali penjumlahan konstanta terakhir.", "e": "Nilainya satu lebih kecil; jangan mengurangi konstanta pada f."}','{"a": 4, "b": 3, "c": 3, "x": 2, "kind": "compose_linear_value"}',1),(9,'CON-R-009','rendah',9,'nilai_dan_rumus_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menghitung nilai komposisi dua fungsi linear secara berurutan.','Diketahui f(x)=2x+4 dan g(x)=x+4. Nilai (f o g)(3) adalah ...','17','20','16','18','19','d','Mulailah dengan menghitung g(3).','g(3)=7. Substitusikan nilai ini ke f.','g(3)=3+4=7. Selanjutnya f(7)=2(7)+4=18.','{"a": "Nilainya satu lebih kecil; jangan mengurangi konstanta pada f.", "b": "Anda mungkin menambahkan koefisien f sekali lagi setelah substitusi.", "c": "Anda mungkin mengurangi koefisien f; ikuti operasi pada rumus f apa adanya.", "d": "", "e": "Nilainya satu lebih besar; periksa kembali penjumlahan konstanta terakhir."}','{"a": 2, "b": 4, "c": 4, "x": 3, "kind": "compose_linear_value"}',1),(10,'CON-R-010','rendah',10,'nilai_dan_rumus_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menghitung nilai komposisi dua fungsi linear secara berurutan.','Diketahui f(x)=3x+5 dan g(x)=x+1. Nilai (f o g)(4) adalah ...','21','19','23','17','20','e','Mulailah dengan menghitung g(4).','g(4)=5. Substitusikan nilai ini ke f.','g(4)=4+1=5. Selanjutnya f(5)=3(5)+5=20.','{"a": "Nilainya satu lebih besar; periksa kembali penjumlahan konstanta terakhir.", "b": "Nilainya satu lebih kecil; jangan mengurangi konstanta pada f.", "c": "Anda mungkin menambahkan koefisien f sekali lagi setelah substitusi.", "d": "Anda mungkin mengurangi koefisien f; ikuti operasi pada rumus f apa adanya.", "e": ""}','{"a": 3, "b": 5, "c": 1, "x": 4, "kind": "compose_linear_value"}',1),(11,'CON-R-011','rendah',11,'nilai_dan_rumus_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menghitung nilai komposisi dua fungsi linear secara berurutan.','Diketahui f(x)=4x+1 dan g(x)=x+2. Nilai (f o g)(5) adalah ...','29','30','28','33','25','a','Mulailah dengan menghitung g(5).','g(5)=7. Substitusikan nilai ini ke f.','g(5)=5+2=7. Selanjutnya f(7)=4(7)+1=29.','{"a": "", "b": "Nilainya satu lebih besar; periksa kembali penjumlahan konstanta terakhir.", "c": "Nilainya satu lebih kecil; jangan mengurangi konstanta pada f.", "d": "Anda mungkin menambahkan koefisien f sekali lagi setelah substitusi.", "e": "Anda mungkin mengurangi koefisien f; ikuti operasi pada rumus f apa adanya."}','{"a": 4, "b": 1, "c": 2, "x": 5, "kind": "compose_linear_value"}',1),(12,'CON-R-012','rendah',12,'nilai_dan_rumus_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menghitung nilai komposisi dua fungsi linear secara berurutan.','Diketahui f(x)=2x+2 dan g(x)=x+3. Nilai (f o g)(6) adalah ...','18','20','21','19','22','b','Mulailah dengan menghitung g(6).','g(6)=9. Substitusikan nilai ini ke f.','g(6)=6+3=9. Selanjutnya f(9)=2(9)+2=20.','{"a": "Anda mungkin mengurangi koefisien f; ikuti operasi pada rumus f apa adanya.", "b": "", "c": "Nilainya satu lebih besar; periksa kembali penjumlahan konstanta terakhir.", "d": "Nilainya satu lebih kecil; jangan mengurangi konstanta pada f.", "e": "Anda mungkin menambahkan koefisien f sekali lagi setelah substitusi."}','{"a": 2, "b": 2, "c": 3, "x": 6, "kind": "compose_linear_value"}',1),(13,'CON-R-013','rendah',13,'nilai_dan_rumus_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menghitung nilai komposisi dua fungsi linear secara berurutan.','Diketahui f(x)=3x+3 dan g(x)=x+4. Nilai (f o g)(7) adalah ...','39','33','36','37','35','c','Mulailah dengan menghitung g(7).','g(7)=11. Substitusikan nilai ini ke f.','g(7)=7+4=11. Selanjutnya f(11)=3(11)+3=36.','{"a": "Anda mungkin menambahkan koefisien f sekali lagi setelah substitusi.", "b": "Anda mungkin mengurangi koefisien f; ikuti operasi pada rumus f apa adanya.", "c": "", "d": "Nilainya satu lebih besar; periksa kembali penjumlahan konstanta terakhir.", "e": "Nilainya satu lebih kecil; jangan mengurangi konstanta pada f."}','{"a": 3, "b": 3, "c": 4, "x": 7, "kind": "compose_linear_value"}',1),(14,'CON-R-014','rendah',14,'nilai_dan_rumus_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menghitung nilai komposisi dua fungsi linear secara berurutan.','Diketahui f(x)=4x+4 dan g(x)=x+1. Nilai (f o g)(8) adalah ...','39','44','36','40','41','d','Mulailah dengan menghitung g(8).','g(8)=9. Substitusikan nilai ini ke f.','g(8)=8+1=9. Selanjutnya f(9)=4(9)+4=40.','{"a": "Nilainya satu lebih kecil; jangan mengurangi konstanta pada f.", "b": "Anda mungkin menambahkan koefisien f sekali lagi setelah substitusi.", "c": "Anda mungkin mengurangi koefisien f; ikuti operasi pada rumus f apa adanya.", "d": "", "e": "Nilainya satu lebih besar; periksa kembali penjumlahan konstanta terakhir."}','{"a": 4, "b": 4, "c": 1, "x": 8, "kind": "compose_linear_value"}',1),(15,'CON-R-015','rendah',15,'menentukan_fungsi_penyusun','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menentukan fungsi luar linear ketika komposisi dan fungsi dalam diketahui.','Jika g(x)=x+2 dan (f o g)(x)=3x+8, maka f(x)=...','3x+3','3x+4','3x+5','3x+6','3x+2','e','Misalkan f(x)=3x+d. Cari nilai d.','f(g(x))=3(x+2)+d=3x+6+d.','Samakan konstanta: 6+d=8, sehingga d=2. Jadi f(x)=3x+2.','{"a": "Konstantanya lebih satu; kurangkan kontribusi dari g secara tepat.", "b": "Konstantanya lebih dua; ingat konstanta g juga dikalikan koefisien f.", "c": "Konstantanya lebih tiga; jangan langsung menyalin konstanta komposisi.", "d": "Konstantanya lebih empat; selesaikan persamaan konstanta sebelum memilih.", "e": ""}','{"a": 3, "c": 2, "q": 8, "kind": "recover_outer_linear"}',1),(16,'CON-R-016','rendah',16,'menentukan_fungsi_penyusun','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menentukan fungsi luar linear ketika komposisi dan fungsi dalam diketahui.','Jika g(x)=x+3 dan (f o g)(x)=4x+15, maka f(x)=...','4x+3','4x+4','4x+5','4x+6','4x+7','a','Misalkan f(x)=4x+d. Cari nilai d.','f(g(x))=4(x+3)+d=4x+12+d.','Samakan konstanta: 12+d=15, sehingga d=3. Jadi f(x)=4x+3.','{"a": "", "b": "Konstantanya lebih satu; kurangkan kontribusi dari g secara tepat.", "c": "Konstantanya lebih dua; ingat konstanta g juga dikalikan koefisien f.", "d": "Konstantanya lebih tiga; jangan langsung menyalin konstanta komposisi.", "e": "Konstantanya lebih empat; selesaikan persamaan konstanta sebelum memilih."}','{"a": 4, "c": 3, "q": 15, "kind": "recover_outer_linear"}',1),(17,'CON-R-017','rendah',17,'menentukan_fungsi_penyusun','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menentukan fungsi luar linear ketika komposisi dan fungsi dalam diketahui.','Jika g(x)=x+1 dan (f o g)(x)=2x+6, maka f(x)=...','2x+8','2x+4','2x+5','2x+6','2x+7','b','Misalkan f(x)=2x+d. Cari nilai d.','f(g(x))=2(x+1)+d=2x+2+d.','Samakan konstanta: 2+d=6, sehingga d=4. Jadi f(x)=2x+4.','{"a": "Konstantanya lebih empat; selesaikan persamaan konstanta sebelum memilih.", "b": "", "c": "Konstantanya lebih satu; kurangkan kontribusi dari g secara tepat.", "d": "Konstantanya lebih dua; ingat konstanta g juga dikalikan koefisien f.", "e": "Konstantanya lebih tiga; jangan langsung menyalin konstanta komposisi."}','{"a": 2, "c": 1, "q": 6, "kind": "recover_outer_linear"}',1),(18,'CON-R-018','rendah',18,'menentukan_fungsi_penyusun','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menentukan fungsi luar linear ketika komposisi dan fungsi dalam diketahui.','Jika g(x)=x+2 dan (f o g)(x)=3x+11, maka f(x)=...','3x+8','3x+9','3x+5','3x+6','3x+7','c','Misalkan f(x)=3x+d. Cari nilai d.','f(g(x))=3(x+2)+d=3x+6+d.','Samakan konstanta: 6+d=11, sehingga d=5. Jadi f(x)=3x+5.','{"a": "Konstantanya lebih tiga; jangan langsung menyalin konstanta komposisi.", "b": "Konstantanya lebih empat; selesaikan persamaan konstanta sebelum memilih.", "c": "", "d": "Konstantanya lebih satu; kurangkan kontribusi dari g secara tepat.", "e": "Konstantanya lebih dua; ingat konstanta g juga dikalikan koefisien f."}','{"a": 3, "c": 2, "q": 11, "kind": "recover_outer_linear"}',1),(19,'CON-R-019','rendah',19,'menentukan_fungsi_penyusun','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menentukan fungsi luar linear ketika komposisi dan fungsi dalam diketahui.','Jika g(x)=x+3 dan (f o g)(x)=4x+18, maka f(x)=...','4x+8','4x+9','4x+10','4x+6','4x+7','d','Misalkan f(x)=4x+d. Cari nilai d.','f(g(x))=4(x+3)+d=4x+12+d.','Samakan konstanta: 12+d=18, sehingga d=6. Jadi f(x)=4x+6.','{"a": "Konstantanya lebih dua; ingat konstanta g juga dikalikan koefisien f.", "b": "Konstantanya lebih tiga; jangan langsung menyalin konstanta komposisi.", "c": "Konstantanya lebih empat; selesaikan persamaan konstanta sebelum memilih.", "d": "", "e": "Konstantanya lebih satu; kurangkan kontribusi dari g secara tepat."}','{"a": 4, "c": 3, "q": 18, "kind": "recover_outer_linear"}',1),(20,'CON-R-020','rendah',20,'sifat_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menjelaskan bahwa komposisi fungsi pada umumnya tidak komutatif.','Untuk f(x)=x+1 dan g(x)=2x, hasil (f o g)(x)=2x+1 sedangkan (g o f)(x)=2x+2. Sifat yang tampak adalah ...','Komposisi selalu komutatif','f adalah fungsi identitas','g adalah fungsi identitas','Urutan komposisi tidak penting','Komposisi tidak komutatif','e','Bandingkan kedua hasil yang diberikan pada soal.','Jika f o g berbeda dari g o f, pertukaran urutan mengubah hasil.','Karena kedua hasil berbeda, f o g tidak selalu sama dengan g o f. Jadi komposisi fungsi tidak komutatif.','{"a": "Pernyataan selalu komutatif bertentangan dengan dua hasil yang berbeda.", "b": "Fungsi identitas harus memetakan x menjadi x, sedangkan f(x)=x+c.", "c": "g(x)=2x bukan fungsi identitas karena mengubah nilai x.", "d": "Urutan justru penting karena kedua komposisi menghasilkan konstanta berbeda.", "e": ""}','{"kind": "literal", "expected": "Komposisi tidak komutatif"}',1),(21,'CON-R-021','rendah',21,'sifat_komposisi','Pada akhir Fase F, peserta didik mampu menerapkan operasi komposisi dan invers fungsi untuk menyelesaikan masalah.','Menjelaskan